Review this JavaScript:

```js
function dedupeById(rows) {
  const seen = new Set();
  const out = [];
  for (const r of rows) {
    if (!seen.has(r.id)) {
      seen.add(r.id);
      out.push(r);
    }
  }
  return out;
}
```

